    homework = '[{"id":"hw1","type":"open","question":{"en":"Activity 1: In groups of 3 or 4, discuss the major causes and solutions of traffic accidents in Ethiopia. Use the table (breaking traffic rules, overloading, poor quality of roads / respecting traffic rules, awareness creation, road maintenance) and add your own ideas.","am":"ተግባር 1፦ በ3 ወይም በ4 ቡድን ሆናችሁ በኢትዮጵያ የትራፊክ አደጋዎችን ዋና መንስኤዎችና መፍትሔዎች ተወያዩ። ሰንጠረዡን ተጠቀሙ፣ የራሳችሁንም ሐሳብ ጨምሩ።"},"tip":{"en":"Match each cause with a solution: rules ↔ respecting rules, overloading ↔ awareness, roads ↔ maintenance.","am":"እያንዳንዱን መንስኤ ከመፍትሔ ጋር አዛምዱ፦ ሕግ ↔ ሕግ ማክበር፣ ከአቅም በላይ መጫን ↔ ግንዛቤ፣ መንገድ ↔ ጥገና።"},"hints":[{"en":"Start with: \"One major cause of traffic accidents is ... because ...\"","am":"እንዲህ ጀምሩ፦ \"One major cause of traffic accidents is ... because ...\""},{"en":"Give a solution with must/should: \"Drivers should ...\", \"The government must ...\"","am":"በmust/should መፍትሔ ስጡ፦ \"Drivers should ...\"፣ \"The government must ...\""}],"answers":[],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"Cause: Many drivers break traffic rules, e.g. they drive too fast.","am":"መንስኤ፦ ብዙ አሽከርካሪዎች የትራፊክ ሕግ ይጥሳሉ፤ ለምሳሌ በጣም በፍጥነት ያሽከረክራሉ።"},"why":{"en":"Speeding gives the driver no time to stop.","am":"ፍጥነት ለአሽከርካሪው ለማቆም ጊዜ አይሰጥም።"}},{"text":{"en":"Cause: Minibuses and trucks are often overloaded.","am":"መንስኤ፦ ሚኒባሶችና የጭነት መኪናዎች ብዙ ጊዜ ከአቅም በላይ ይጫናሉ።"},"why":{"en":"An overloaded vehicle is hard to control.","am":"ከአቅም በላይ የተጫነ ተሽከርካሪ ለመቆጣጠር አስቸጋሪ ነው።"}},{"text":{"en":"Solutions: respect traffic rules, create awareness through the media and schools, and maintain the roads.","am":"መፍትሔዎች፦ የትራፊክ ሕግን ማክበር፣ በመገናኛ ብዙኃንና በትምህርት ቤቶች ግንዛቤ መፍጠር፣ መንገዶችን መጠገን።"}}],"answer":{"en":"Model answer: \"One major cause is breaking traffic rules. Drivers should respect the rules, and the government must create awareness and maintain the roads.\"","am":"የሞዴል መልስ፦ \"One major cause is breaking traffic rules. Drivers should respect the rules, and the government must create awareness and maintain the roads.\""}}},{"id":"hw2","type":"open","question":{"en":"Activity 2: Act out the dialogue and complete the missing clauses.\nTewabe: These days, traffic accidents have become a serious problem in our country, isn''t it?\nRegassa: Yes, it is. Several people (1) ______.\nTewabe: What do you think is the reason for that?\nRegassa: Because (2) ______.\nTewabe: What must the government do to solve this problem?\nRegassa: (3) ______.\nTewabe: What about the road users?\nRegassa: (4) ______.\nTewabe: The roads themselves also cause traffic accidents, don''t they?\nRegassa: Yes, they do. (5) ______","am":"ተግባር 2፦ ውይይቱን ተጫወቱ፤ የጎደሉትን ሐረጎች አሟሉ። (ውይይቱ በእንግሊዝኛ ነው፤ ከላይ ያሉትን የመንስኤና የመፍትሔ ሐረጎች ተጠቀሙ።)"},"tip":{"en":"Use the phrases from the causes/solutions table. Answer each question with one full sentence.","am":"ከመንስኤ/መፍትሔ ሰንጠረዡ ሐረጎቹን ተጠቀሙ። እያንዳንዱን ጥያቄ በአንድ ሙሉ ዓረፍተ ነገር መልሱ።"},"hints":[{"en":"(1) is about deaths and injuries. (2) is a cause. (3)–(5) are solutions.","am":"(1) ስለ ሞትና ጉዳት ነው። (2) መንስኤ ነው። (3)–(5) መፍትሔዎች ናቸው።"},{"en":"Use \"must\" for the government and \"should\" for road users.","am":"ለመንግሥት \"must\"፣ ለመንገድ ተጠቃሚዎች \"should\" ተጠቀሙ።"}],"answers":[],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"(1) Several people **lose their lives or are injured every day**.","am":"(1) Several people **lose their lives or are injured every day**."}},{"text":{"en":"(2) Because **many drivers break traffic rules and vehicles are overloaded**.","am":"(2) Because **many drivers break traffic rules and vehicles are overloaded**."}},{"text":{"en":"(3) **The government must create awareness and punish drivers who break the rules.**","am":"(3) **The government must create awareness and punish drivers who break the rules.**"}},{"text":{"en":"(4) **Road users should respect traffic rules and cross at zebra crossings.**","am":"(4) **Road users should respect traffic rules and cross at zebra crossings.**"}},{"text":{"en":"(5) Yes, they do. **Poor-quality roads need regular maintenance.**","am":"(5) Yes, they do. **Poor-quality roads need regular maintenance.**"}}],"answer":{"en":"Any correct, complete sentences that use the causes and solutions are acceptable. The model answers are above.","am":"መንስኤዎቹንና መፍትሔዎቹን የሚጠቀሙ ማንኛውም ትክክለኛና ሙሉ ዓረፍተ ነገሮች ተቀባይነት አላቸው። የሞዴል መልሶቹ ከላይ ናቸው።"}}},{"id":"hw3","type":"open","question":{"en":"Express your agreement on this topic using expressions of agreement: \"Foreign aid does not necessarily solve the problems of developing countries.\"","am":"በዚህ ርዕስ ላይ የመስማማት አገላለጾችን ተጠቅማችሁ መስማማታችሁን ግለጹ፦ \"Foreign aid does not necessarily solve the problems of developing countries.\""},"tip":{"en":"Start with an agreement expression, then give a reason.","am":"በመስማማት አገላለጽ ጀምሩ፣ ከዚያ ምክንያት ስጡ።"},"hints":[{"en":"Choose one: \"I agree with you 100 percent.\" / \"That''s so true.\" / \"You''re absolutely right.\"","am":"አንዱን ምረጡ፦ \"I agree with you 100 percent.\" / \"That''s so true.\" / \"You''re absolutely right.\""},{"en":"Reason idea: countries need their own work, skills and good governance to develop.","am":"የምክንያት ሐሳብ፦ አገሮች ለማደግ የራሳቸው ሥራ፣ ክህሎትና መልካም አስተዳደር ያስፈልጋቸዋል።"}],"answers":[],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"Agreement expression: \"**You''re absolutely right.**\"","am":"የመስማማት አገላለጽ፦ \"**You''re absolutely right.**\""}},{"text":{"en":"Reason: \"Aid helps for a short time, but a country develops through its own work, skills and good governance.\"","am":"ምክንያት፦ \"Aid helps for a short time, but a country develops through its own work, skills and good governance.\""}}],"answer":{"en":"\"You''re absolutely right. Foreign aid helps for a short time, but developing countries must solve their problems through their own work and good governance.\"","am":"\"You''re absolutely right. Foreign aid helps for a short time, but developing countries must solve their problems through their own work and good governance.\""}}},{"id":"hw4","type":"open","question":{"en":"Express your agreement on this topic using expressions of agreement: \"Social media should be censored by the government.\"","am":"በዚህ ርዕስ ላይ የመስማማት አገላለጾችን ተጠቅማችሁ መስማማታችሁን ግለጹ፦ \"Social media should be censored by the government.\""},"tip":{"en":"Agree first, then explain why with one example.","am":"መጀመሪያ ተስማሙ፣ ከዚያ ለምን እንደሆነ በአንድ ምሳሌ አብራሩ።"},"hints":[{"en":"Try: \"That''s exactly how I feel.\" or \"No doubt about it.\"","am":"ሞክሩ፦ \"That''s exactly how I feel.\" ወይም \"No doubt about it.\""},{"en":"Reason idea: fake news and hate speech can cause conflict.","am":"የምክንያት ሐሳብ፦ የሐሰት ዜናና የጥላቻ ንግግር ግጭት ሊያስከትሉ ይችላሉ።"}],"answers":[],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"Agreement expression: \"**That''s exactly how I feel.**\"","am":"የመስማማት አገላለጽ፦ \"**That''s exactly how I feel.**\""}},{"text":{"en":"Reason: \"Fake news and hate speech spread fast and can cause conflict.\"","am":"ምክንያት፦ \"Fake news and hate speech spread fast and can cause conflict.\""}}],"answer":{"en":"\"That''s exactly how I feel. Some control is needed because fake news and hate speech spread fast on social media and can cause conflict.\"","am":"\"That''s exactly how I feel. Some control is needed because fake news and hate speech spread fast on social media and can cause conflict.\""}}},{"id":"hw5","type":"choice","question":{"en":"Vina: Do you think browsing on the internet is difficult?\nDea: Mm… **I don''t think so.** We just need more practice.\nThe bold sentence expresses:","am":"Vina: Do you think browsing on the internet is difficult?\nDea: Mm… **I don''t think so.** We just need more practice.\nበደማቅ የተጻፈው ዓረፍተ ነገር የሚገልጸው፦"},"tip":{"en":"\"I don''t think so\" is in the disagreement list.","am":"\"I don''t think so\" በአለመስማማት ዝርዝር ውስጥ አለ።"},"hints":[{"en":"Does Dea think it is difficult?","am":"ዴያ አስቸጋሪ ነው ብላ ታስባለች?"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","correct":2,"options":[{"en":"A. asking opinion","am":"A. asking opinion"},{"en":"B. agreement","am":"B. agreement"},{"en":"C. disagreement","am":"C. disagreement"},{"en":"D. satisfaction","am":"D. satisfaction"},{"en":"E. dissatisfaction","am":"E. dissatisfaction"}]}}],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"Vina thinks it is difficult; Dea does not, so she disagrees.","am":"ቪና አስቸጋሪ ነው ትላለች፤ ዴያ አትስማማም፣ ስለዚህ አለመስማማት ነው።"}}],"answer":{"en":"C. disagreement","am":"C. disagreement (አለመስማማት)"}}},{"id":"hw6","type":"choice","question":{"en":"Chen: I''m thinking about going camping next holiday. What do you think?\nChan: **It''s great I think.**\nThe bold expression shows:","am":"Chen: I''m thinking about going camping next holiday. What do you think?\nChan: **It''s great I think.**\nበደማቅ የተጻፈው አገላለጽ የሚያሳየው፦"},"tip":{"en":"Chan likes Chen''s plan. Is that for or against it?","am":"ቻን የቼንን ዕቅድ ይወደዋል። ይህ ይደግፋል ወይስ ይቃወማል?"},"hints":[{"en":"Chen asks for an opinion; Chan supports the idea.","am":"ቼን አስተያየት ይጠይቃል፤ ቻን ሐሳቡን ይደግፋል።"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","correct":4,"options":[{"en":"A. possibility","am":"A. possibility"},{"en":"B. satisfaction","am":"B. satisfaction"},{"en":"C. sympathy","am":"C. sympathy"},{"en":"D. ability","am":"D. ability"},{"en":"E. agreement","am":"E. agreement"}]}}],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"Chan supports Chen''s plan, so he agrees with it.","am":"ቻን የቼንን ዕቅድ ይደግፋል፤ ስለዚህ ይስማማል።"}}],"answer":{"en":"E. agreement","am":"E. agreement (መስማማት)"}}},{"id":"hw7","type":"choice","question":{"en":"Bill: Do you agree that the school''s new regulation is disappointing?\nBob: No, ______ because it is better than the previous one.\nThe suitable expression is:","am":"Bill: Do you agree that the school''s new regulation is disappointing?\nBob: No, ______ because it is better than the previous one.\nተስማሚው አገላለጽ፦"},"tip":{"en":"Bob starts with \"No\", so he disagrees.","am":"ቦብ በ\"No\" ይጀምራል፤ ስለዚህ አይስማማም።"},"hints":[{"en":"Find the only disagreement expression.","am":"ብቸኛውን የአለመስማማት አገላለጽ ፈልጉ።"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","correct":2,"options":[{"en":"A. I''m 100 percent agree with you","am":"A. I''m 100 percent agree with you"},{"en":"B. I get along with you","am":"B. I get along with you"},{"en":"C. I entirely disagree with you.","am":"C. I entirely disagree with you."},{"en":"D. I suppose so.","am":"D. I suppose so."},{"en":"E. I dare you are right","am":"E. I dare you are right"}]}}],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"\"No ... because it is better\" needs a disagreement expression; A, B, D and E all agree.","am":"\"No ... because it is better\" የአለመስማማት አገላለጽ ይፈልጋል፤ A፣ B፣ D እና E ሁሉም መስማማትን ያሳያሉ።"}}],"answer":{"en":"C. I entirely disagree with you.","am":"C. I entirely disagree with you."}}},{"id":"hw8","type":"choice","question":{"en":"Jack: What do you think of our new jackets?\nJill: It''s a lovely jacket. I''m satisfied with the model.\nJane: Yes, ______. I like the model. We''d better order again next year.","am":"Jack: What do you think of our new jackets?\nJill: It''s a lovely jacket. I''m satisfied with the model.\nJane: Yes, ______. I like the model. We''d better order again next year."},"tip":{"en":"Jane says \"Yes\" and likes the model: she agrees.","am":"ጄን \"Yes\" ትላለች፣ ሞዴሉንም ትወደዋለች፤ ትስማማለች።"},"hints":[{"en":"Only one option shows agreement.","am":"መስማማትን የሚያሳየው አንድ አማራጭ ብቻ ነው።"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","correct":0,"options":[{"en":"A. I get along with your opinion","am":"A. I get along with your opinion"},{"en":"B. Not really","am":"B. Not really"},{"en":"C. I can''t accept it","am":"C. I can''t accept it"},{"en":"D. I''m not sure about that","am":"D. I''m not sure about that"},{"en":"E. Well, it depends","am":"E. Well, it depends"}]}}],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"B, C and D disagree; E is unsure. Only A agrees with Jill.","am":"B፣ C እና D አይስማሙም፤ E እርግጠኛ አይደለም። ከጂል ጋር የሚስማማው A ብቻ ነው።"}}],"answer":{"en":"A. I get along with your opinion","am":"A. I get along with your opinion"}}},{"id":"hw9","type":"choice","question":{"en":"Tanaka: Have you heard that Mr. Chan has been promoted to be the area manager?\nOmura: I think he is the right person for that position.\nKeiko: ______ because his experience and educational background are great.","am":"Tanaka: Have you heard that Mr. Chan has been promoted to be the area manager?\nOmura: I think he is the right person for that position.\nKeiko: ______ because his experience and educational background are great."},"tip":{"en":"Keiko praises Mr. Chan, so she agrees with Omura.","am":"ኬይኮ ሚስተር ቻንን ታመሰግናለች፤ ስለዚህ ከኦሙራ ጋር ትስማማለች።"},"hints":[{"en":"\"No objection\" = no reason to disagree.","am":"\"No objection\" = ለመቃወም ምክንያት የለም።"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","correct":1,"options":[{"en":"A. I wouldn''t accept that","am":"A. I wouldn''t accept that"},{"en":"B. I don''t have any objection to it","am":"B. I don''t have any objection to it"},{"en":"C. I''m afraid you are wrong","am":"C. I''m afraid you are wrong"},{"en":"D. I don''t agree with you at all","am":"D. I don''t agree with you at all"},{"en":"E. Not necessarily","am":"E. Not necessarily"}]}}],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"All options except B express disagreement.","am":"ከB በስተቀር ሁሉም አማራጮች አለመስማማትን ይገልጻሉ።"}}],"answer":{"en":"B. I don''t have any objection to it","am":"B. I don''t have any objection to it"}}},{"id":"hw10","type":"choice","question":{"en":"Odi: I think English is a very difficult language to learn.\nSteven: Do you think so? You just need practice every day and it will be very easy.\nWhat does Steven mean?","am":"Odi: I think English is a very difficult language to learn.\nSteven: Do you think so? You just need practice every day and it will be very easy.\nስቲቨን ምን ማለቱ ነው?"},"tip":{"en":"Odi says \"difficult\"; Steven says \"very easy\".","am":"ኦዲ \"አስቸጋሪ\" ይላል፤ ስቲቨን \"በጣም ቀላል\" ይላል።"},"hints":[{"en":"Opposite opinions = disagreement.","am":"ተቃራኒ አስተያየቶች = አለመስማማት።"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","correct":3,"options":[{"en":"A. He is not satisfied with Odi''s opinion","am":"A. He is not satisfied with Odi''s opinion"},{"en":"B. He feels regret on Odi''s opinion","am":"B. He feels regret on Odi''s opinion"},{"en":"C. He agrees with Odi''s opinion","am":"C. He agrees with Odi''s opinion"},{"en":"D. He disagrees with Odi''s opinion","am":"D. He disagrees with Odi''s opinion"}]}}],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"Steven thinks English becomes easy with practice, the opposite of Odi''s opinion.","am":"ስቲቨን እንግሊዝኛ በልምምድ ቀላል ይሆናል ብሎ ያስባል፤ ይህ የኦዲ ተቃራኒ ነው።"}}],"answer":{"en":"D. He disagrees with Odi''s opinion","am":"D. He disagrees with Odi''s opinion"}}},{"id":"hw11","type":"choice","question":{"en":"Mother: Television has a bad influence on children.\nFather: That''s exactly my opinion. We should limit their time for watching TV.\nWhat does the father mean?","am":"Mother: Television has a bad influence on children.\nFather: That''s exactly my opinion. We should limit their time for watching TV.\nአባትየው ምን ማለቱ ነው?"},"tip":{"en":"\"That''s exactly my opinion\" = same opinion.","am":"\"That''s exactly my opinion\" = ተመሳሳይ አስተያየት።"},"hints":[{"en":"He even adds a solution that supports Mother''s idea.","am":"የእናትን ሐሳብ የሚደግፍ መፍትሔም ይጨምራል።"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","correct":0,"options":[{"en":"A. He agrees with mother","am":"A. He agrees with mother"},{"en":"B. He disagrees with mother","am":"B. He disagrees with mother"},{"en":"C. He has no opinion","am":"C. He has no opinion"},{"en":"D. He feels regret to have no opinion","am":"D. He feels regret to have no opinion"}]}}],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"\"That''s exactly my opinion\" is a strong expression of agreement.","am":"\"That''s exactly my opinion\" ጠንካራ የመስማማት አገላለጽ ነው።"}}],"answer":{"en":"A. He agrees with mother","am":"A. He agrees with mother"}}},{"id":"hw12","type":"choice","question":{"en":"Lea: I think ''dangdut'' music is only appropriate for villagers.\nSam: I''m afraid you''re wrong. It has become popular; even high-class people enjoy dangdut.\nWhat is Sam''s opinion towards Lea''s?","am":"Lea: I think ''dangdut'' music is only appropriate for villagers.\nSam: I''m afraid you''re wrong. It has become popular; even high-class people enjoy dangdut.\nሳም ለሊያ አስተያየት ያለው አመለካከት ምንድን ነው?"},"tip":{"en":"\"I''m afraid you''re wrong\" sounds polite, but what does it mean?","am":"\"I''m afraid you''re wrong\" ጨዋ ይመስላል፤ ግን ምን ማለት ነው?"},"hints":[{"en":"\"I''m afraid\" here does not mean fear; it softens a disagreement.","am":"እዚህ \"I''m afraid\" ፍርሃት ማለት አይደለም፤ አለመስማማትን ያለሰልሳል።"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","correct":1,"options":[{"en":"A. He agrees","am":"A. He agrees"},{"en":"B. He disagrees","am":"B. He disagrees"},{"en":"C. He has no opinion","am":"C. He has no opinion"},{"en":"D. He is satisfied","am":"D. He is satisfied"},{"en":"E. He is happy","am":"E. He is happy"}]}}],"needs_calculation":false,"solution":{"steps":[{"text":{"en":"Sam says Lea is wrong and gives the opposite fact, so he disagrees.","am":"ሳም ሊያ ተሳስታለች ብሎ ተቃራኒ እውነታ ይሰጣል፤ ስለዚህ አይስማማም።"}}],"answer":{"en":"B. He disagrees","am":"B. He disagrees"}}}]'::jsonb, practice = '[]'::jsonb
  where id = v_lesson_id;

  insert into public.lesson_sections (lesson_id, sort_order, title_en, title_am, icon, blocks) values
    (v_lesson_id, 1, 'Causes and solutions', 'መንስኤዎችና መፍትሔዎች', 'route',
     '[{"type":"paragraph","text":{"en":"Road traffic accidents have become a **serious problem** in Ethiopia. Many people die or are injured every year.","am":"የመንገድ ትራፊክ አደጋዎች በኢትዮጵያ **ከባድ ችግር** ሆነዋል። በየዓመቱ ብዙ ሰዎች ይሞታሉ ወይም ይጎዳሉ።"}},{"type":"table","headers":[{"en":"Cause","am":"መንስኤ"},{"en":"Solution","am":"መፍትሔ"}],"rows":[[{"en":"breaking traffic rules","am":"breaking traffic rules (የትራፊክ ሕግ መጣስ)"},{"en":"respecting traffic rules","am":"respecting traffic rules (የትራፊክ ሕግ ማክበር)"}],[{"en":"overloading","am":"overloading (ከአቅም በላይ መጫን)"},{"en":"awareness creation","am":"awareness creation (ግንዛቤ መፍጠር)"}],[{"en":"poor quality of roads","am":"poor quality of roads (ደካማ የመንገድ ጥራት)"},{"en":"road maintenance","am":"road maintenance (የመንገድ ጥገና)"}]]},{"type":"example","title":{"en":"More causes you can mention","am":"ሌሎች ልትጠቅሷቸው የምትችሉ መንስኤዎች"},"text":{"en":"excessive speeding, poor driving skills, drunk driving, using a phone while driving, old vehicles.","am":"excessive speeding (ከልክ ያለፈ ፍጥነት)፣ poor driving skills (ደካማ የማሽከርከር ክህሎት)፣ drunk driving (ጠጥቶ ማሽከርከር)፣ በማሽከርከር ላይ ስልክ መጠቀም፣ ያረጁ ተሽከርካሪዎች።"}}]'::jsonb),
    (v_lesson_id, 2, 'Talking about the problem', 'ስለ ችግሩ መናገር', 'quote',
     '[{"type":"paragraph","text":{"en":"Useful sentence patterns for a dialogue about traffic accidents:","am":"ስለ ትራፊክ አደጋ ለሚደረግ ውይይት ጠቃሚ የዓረፍተ ነገር አወቃቀሮች፦"}},{"type":"list","items":[{"en":"\"Several people **lose their lives** every day.\"","am":"\"Several people **lose their lives** every day.\" (በየቀኑ ብዙ ሰዎች ሕይወታቸውን ያጣሉ።)"},{"en":"\"It is **because** drivers break traffic rules.\"","am":"\"It is **because** drivers break traffic rules.\" (ምክንያቱም አሽከርካሪዎች የትራፊክ ሕግ ስለሚጥሱ ነው።)"},{"en":"\"The government **must** maintain the roads.\"","am":"\"The government **must** maintain the roads.\" (መንግሥት መንገዶችን መጠገን አለበት።)"},{"en":"\"Road users **should** respect traffic rules.\"","am":"\"Road users **should** respect traffic rules.\" (የመንገድ ተጠቃሚዎች የትራፊክ ሕግን ማክበር አለባቸው።)"}]},{"type":"tip","title":{"en":"Grammar link","am":"የሰዋስው ትስስር"},"text":{"en":"Use **must** and **should** (expressing obligation, lesson 3.4) to give solutions.","am":"መፍትሔ ለመስጠት **must** እና **should** (ግዴታን መግለጽ፣ ትምህርት 3.4) ተጠቀሙ።"}}]'::jsonb),
    (v_lesson_id, 3, 'Expressing agreement', 'መስማማትን መግለጽ', 'list-checks',
     '[{"type":"keypoint","variant":"definition","title":{"en":"Agreement","am":"መስማማት (Agreement)"},"text":{"en":"We express **agreement** when we have the same opinion as the speaker.","am":"ከተናጋሪው ጋር ተመሳሳይ አስተያየት ሲኖረን **መስማማትን (Agreement)** እንገልጻለን።"}},{"type":"terms","title":{"en":"Strong agreement","am":"ጠንካራ መስማማት"},"items":[{"en":"I agree with you 100 percent.","am":"I agree with you 100 percent. (መቶ በመቶ እስማማለሁ)"},{"en":"That''s so true.","am":"That''s so true. (በጣም እውነት ነው)"},{"en":"That''s for sure.","am":"That''s for sure. (እርግጠኛ ነው)"},{"en":"You''re absolutely right.","am":"You''re absolutely right. (ፍጹም ትክክል ነህ/ነሽ)"}]},{"type":"terms","title":{"en":"Strong agreement (more)","am":"ጠንካራ መስማማት (ተጨማሪ)"},"items":[{"en":"Absolutely. / Exactly.","am":"Absolutely. / Exactly. (በትክክል)"},{"en":"That''s exactly how I feel.","am":"That''s exactly how I feel. (እኔም ልክ እንደዚያ ይሰማኛል)"},{"en":"No doubt about it.","am":"No doubt about it. (ምንም ጥርጥር የለውም)"},{"en":"I was just going to say that.","am":"I was just going to say that. (እኔም ያንኑ ልናገር ነበር)"}]}]'::jsonb),
    (v_lesson_id, 4, 'Weak (partial) agreement', 'ደካማ (ከፊል) መስማማት', 'scale',
     '[{"type":"paragraph","text":{"en":"Sometimes we agree, but **not completely**. We use weaker expressions:","am":"አንዳንድ ጊዜ እንስማማለን፣ ግን **ሙሉ በሙሉ አይደለም**። ደካማ አገላለጾችን እንጠቀማለን፦"}},{"type":"terms","title":{"en":"Weak agreement","am":"ደካማ መስማማት"},"items":[{"en":"I suppose so. / I guess so.","am":"I suppose so. / I guess so. (እንደዚያ ይመስለኛል)"},{"en":"You have a point there.","am":"You have a point there. (እዚያ ላይ ትክክል ነህ/ነሽ)"},{"en":"I have to side with Dad on this one.","am":"I have to side with Dad on this one. (በዚህ ጉዳይ ከአባቴ ጋር እቆማለሁ)"},{"en":"I don''t have any objection to it.","am":"I don''t have any objection to it. (ምንም ተቃውሞ የለኝም)"}]},{"type":"example","title":{"en":"In a dialogue","am":"በውይይት ውስጥ"},"text":{"en":"Mother: Television has a bad influence on children.\nFather: **That''s exactly my opinion.** We should limit their time for watching TV.","am":"እናት፦ Television has a bad influence on children.\nአባት፦ **That''s exactly my opinion.** (ሙሉ በሙሉ እስማማለሁ።) We should limit their time for watching TV."}}]'::jsonb),
    (v_lesson_id, 5, 'Expressing disagreement', 'አለመስማማትን መግለጽ', 'circle-help',
     '[{"type":"keypoint","variant":"definition","title":{"en":"Disagreement","am":"አለመስማማት (Disagreement)"},"text":{"en":"We express **disagreement** when our opinion is different. Polite expressions keep the discussion friendly.","am":"አስተያየታችን የተለየ ሲሆን **አለመስማማትን (Disagreement)** እንገልጻለን። ጨዋ አገላለጾች ውይይቱን ወዳጃዊ ያደርጉታል።"}},{"type":"terms","title":{"en":"Polite disagreement","am":"ጨዋ አለመስማማት"},"items":[{"en":"I don''t think so.","am":"I don''t think so. (እንደዚያ አይመስለኝም)"},{"en":"I''m afraid I disagree.","am":"I''m afraid I disagree. (ይቅርታ፣ አልስማማም)"},{"en":"I beg to differ.","am":"I beg to differ. (በአክብሮት የተለየ አስተያየት አለኝ)"},{"en":"Not necessarily.","am":"Not necessarily. (የግድ አይደለም)"}]},{"type":"terms","title":{"en":"Polite disagreement (more)","am":"ጨዋ አለመስማማት (ተጨማሪ)"},"items":[{"en":"That''s not always true / the case.","am":"That''s not always true / the case. (ሁልጊዜ እውነት አይደለም)"},{"en":"No, I''m not so sure about that.","am":"No, I''m not so sure about that. (አይ፣ በዚያ ላይ እርግጠኛ አይደለሁም)"},{"en":"I don''t think I agree with you.","am":"I don''t think I agree with you. (የምስማማህ/የምስማማሽ አይመስለኝም)"}]}]'::jsonb),
    (v_lesson_id, 6, 'Strong disagreement', 'ጠንካራ አለመስማማት', 'target',
     '[{"type":"terms","title":{"en":"Strong disagreement","am":"ጠንካራ አለመስማማት"},"items":[{"en":"No way.","am":"No way. (በፍጹም)"},{"en":"I totally disagree.","am":"I totally disagree. (ፈጽሞ አልስማማም)"},{"en":"I''d say the exact opposite.","am":"I''d say the exact opposite. (እኔ ተቃራኒውን ነው የምለው)"},{"en":"I can''t accept it.","am":"I can''t accept it. (ልቀበለው አልችልም)"},{"en":"I''m afraid you''re wrong.","am":"I''m afraid you''re wrong. (ይቅርታ፣ ተሳስተሃል/ተሳስተሻል)"}]},{"type":"example","title":{"en":"In a dialogue","am":"በውይይት ውስጥ"},"text":{"en":"Lea: I think ''dangdut'' music is only for villagers.\nSam: **I''m afraid you''re wrong.** Even high-class people enjoy it.","am":"ሊያ፦ I think ''dangdut'' music is only for villagers.\nሳም፦ **I''m afraid you''re wrong.** (አልስማማም።) Even high-class people enjoy it."}},{"type":"tip","title":{"en":"Exam trap","am":"የፈተና ወጥመድ"},"text":{"en":"Don''t be fooled by politeness: **\"I''m afraid...\"** and **\"I beg to differ\"** sound soft but they mean **disagreement**.","am":"በጨዋነቱ አትታለሉ፦ **\"I''m afraid...\"** እና **\"I beg to differ\"** ለስላሳ ቢመስሉም **አለመስማማትን** ያመለክታሉ።"}}]'::jsonb);

  insert into public.quizzes (lesson_id, title_en, title_am, description_en, description_am)
  values (v_lesson_id, 'Quiz: Agreeing and Disagreeing', 'ፈተና፦ መስማማትና አለመስማማት', '10 questions: is it agreement or disagreement? Plus traffic-accident vocabulary.', '10 ጥያቄዎች፦ መስማማት ነው ወይስ አለመስማማት? እና የትራፊክ አደጋ ቃላት።')
  returning id into v_quiz_id;

  insert into public.quiz_questions (quiz_id, sort_order, kind, needs_calculation, question_en, question_am, options_en, options_am, correct_index, answer, steps, guide, explanation_en, explanation_am) values
    (v_quiz_id, 1, 'choice', false, '"I beg to differ." expresses:', '"I beg to differ." የሚገልጸው፦',
     array['Agreement', 'Disagreement', 'Asking for opinion', 'Sympathy']::text[],
     array['መስማማት (Agreement)', 'አለመስማማት (Disagreement)', 'አስተያየት መጠየቅ', 'ማዘን (Sympathy)']::text[],
     1, null, '[]'::jsonb, null,
     '"I beg to differ" is a polite way to say you disagree.', '"I beg to differ" አለመስማማትን በጨዋነት የመግለጫ መንገድ ነው።'),
    (v_quiz_id, 2, 'choice', false, 'Which expression shows STRONG agreement?', 'ጠንካራ መስማማትን የሚያሳየው አገላለጽ የትኛው ነው?',
     array['I suppose so.', 'I agree with you 100 percent.', 'Not necessarily.', 'I guess so.']::text[],
     array['I suppose so.', 'I agree with you 100 percent.', 'Not necessarily.', 'I guess so.']::text[],
     1, null, '[]'::jsonb, null,
     '"100 percent" is full, strong agreement. "I suppose/guess so" are weak.', '"100 percent" ሙሉ፣ ጠንካራ መስማማት ነው። "I suppose/guess so" ደካማ ናቸው።'),
    (v_quiz_id, 3, 'choice', false, 'Which expression shows WEAK agreement?', 'ደካማ መስማማትን የሚያሳየው አገላለጽ የትኛው ነው?',
     array['Absolutely!', 'No doubt about it.', 'I suppose so.', 'You''re absolutely right.']::text[],
     array['Absolutely!', 'No doubt about it.', 'I suppose so.', 'You''re absolutely right.']::text[],
     2, null, '[]'::jsonb, null,
     '"I suppose so" agrees, but without much certainty.', '"I suppose so" ይስማማል፣ ግን ብዙ እርግጠኝነት የለውም።'),
    (v_quiz_id, 4, 'choice', false, 'Which is a STRONG disagreement?', 'ጠንካራ አለመስማማት የትኛው ነው?',
     array['No way.', 'That''s for sure.', 'You have a point there.', 'Exactly.']::text[],
     array['No way.', 'That''s for sure.', 'You have a point there.', 'Exactly.']::text[],
     0, null, '[]'::jsonb, null,
     '"No way" is a strong, direct disagreement.', '"No way" ጠንካራና ቀጥተኛ አለመስማማት ነው።'),
    (v_quiz_id, 5, 'choice', false, '"You have a point there." means:', '"You have a point there." ማለት፦',
     array['I partly agree with you', 'I totally disagree', 'Please point at it', 'I have no opinion']::text[],
     array['በከፊል እስማማለሁ', 'ፈጽሞ አልስማማም', 'እባክህ ጠቁመው', 'አስተያየት የለኝም']::text[],
     0, null, '[]'::jsonb, null,
     'It accepts that the other person''s idea is reasonable: weak agreement.', 'የሌላው ሰው ሐሳብ ምክንያታዊ መሆኑን ይቀበላል፦ ደካማ መስማማት።'),
    (v_quiz_id, 6, 'choice', false, '"That''s not always the case." expresses:', '"That''s not always the case." የሚገልጸው፦',
     array['Agreement', 'Polite disagreement', 'Satisfaction', 'Ability']::text[],
     array['መስማማት', 'ጨዋ አለመስማማት', 'እርካታ', 'ችሎታ']::text[],
     1, null, '[]'::jsonb, null,
     'It politely says the statement is not true every time.', 'አባባሉ ሁልጊዜ እውነት እንዳልሆነ በጨዋነት ይናገራል።'),
    (v_quiz_id, 7, 'choice', false, 'A: "We should all respect traffic rules." B: "______ It would save many lives."', 'A: "We should all respect traffic rules." B: "______ It would save many lives."',
     array['I''d say the exact opposite.', 'That''s so true.', 'I can''t accept it.', 'No way.']::text[],
     array['I''d say the exact opposite.', 'That''s so true.', 'I can''t accept it.', 'No way.']::text[],
     1, null, '[]'::jsonb, null,
     'B supports A''s idea, so an agreement expression fits.', 'B የAን ሐሳብ ይደግፋል፤ ስለዚህ የመስማማት አገላለጽ ይገጥማል።'),
    (v_quiz_id, 8, 'choice', false, 'A: "Overloading never causes accidents." B: "______ Overloaded minibuses are hard to control."', 'A: "Overloading never causes accidents." B: "______ Overloaded minibuses are hard to control."',
     array['I was just going to say that.', 'That''s exactly how I feel.', 'I''m afraid I disagree.', 'No doubt about it.']::text[],
     array['I was just going to say that.', 'That''s exactly how I feel.', 'I''m afraid I disagree.', 'No doubt about it.']::text[],
     2, null, '[]'::jsonb, null,
     'B gives the opposite fact, so B disagrees.', 'B ተቃራኒውን እውነታ ይሰጣል፤ ስለዚህ አይስማማም።'),
    (v_quiz_id, 9, 'choice', false, 'Which one is a SOLUTION to traffic accidents?', 'ለትራፊክ አደጋ መፍትሔ የሆነው የትኛው ነው?',
     array['overloading', 'poor quality of roads', 'awareness creation', 'breaking traffic rules']::text[],
     array['overloading (ከአቅም በላይ መጫን)', 'poor quality of roads (ደካማ መንገድ)', 'awareness creation (ግንዛቤ መፍጠር)', 'breaking traffic rules (ሕግ መጣስ)']::text[],
     2, null, '[]'::jsonb, null,
     'Awareness creation teaches people to behave safely; the others are causes.', 'ግንዛቤ መፍጠር ሰዎች በደኅንነት እንዲንቀሳቀሱ ያስተምራል፤ ሌሎቹ መንስኤዎች ናቸው።'),
    (v_quiz_id, 10, 'choice', false, 'The solution that matches "poor quality of roads" is:', 'ከ"poor quality of roads" ጋር የሚዛመደው መፍትሔ፦',
     array['road maintenance', 'overloading', 'speeding', 'drunk driving']::text[],
     array['road maintenance (የመንገድ ጥገና)', 'overloading', 'speeding', 'drunk driving']::text[],
     0, null, '[]'::jsonb, null,
